import { RoxyAngelNumberLookup as Element } from '@roxyapi/ui-react';
import type { ComponentProps } from 'react';

export type RoxyAngelNumberLookupProps = ComponentProps<typeof Element>;

export function RoxyAngelNumberLookup(props: RoxyAngelNumberLookupProps) {
	return <Element {...props} />;
}

export default RoxyAngelNumberLookup;
